INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1292508-coe399', 'stk-sultan11', 'COE 399', 'info', '{"desc": "أظنّ الكورس هذا ما يتقيّم .\n\nبس لعيون الجميع … و بما إني فاضي بأقيّمة .\n\nأول شي لازم تكون مخلص شغلتين عشان تكون مرشح للتدريب . الأولى ENGL 214 و الثانية تكون Junior . كثير يقولون غير هالكلام بس خلك منهم .\n\nالشي الثاني … لازم تعرف إن فيه 4 كورسات إختيارية من التخصص لازم تاخذها لو طبقت صيفي بعكس طلاب التطبيق التعاوني ياخذون كورسين أو كورس أو لا شي > ماني متأكد .\n\nالشي الثالث وهو الاهم … لازم تعرف أن الحصول على تدريب صيفي هو أمر صعب لكل التخصصات … و صعب أكثر لتخصصنا .\n\nعموماً الحمد لله أخذت التدريب الصيفي في ترم 123 و كنت مع شركة في الرياض . الأهم إن الشركة غالباً بتكون ما هي عارفة وش تسوي بك … فأنصحك بالإطّلاع على مشاريعهم و أختيار شي ممكن تساهم فيه أو تعيد تصميمه … أفضل ما يحطونك في الداتا إنتري ولا شي مكتبي تجلس تتفرج فيهم .\n\nشخصياً أشتغلت على بروجكت له علاقة بالهاردوير بعد نشبة للشركة . أستفدت من البروجكت و أفدت الشركة .\n\nالدروس اللي تعلمتها من التدريب هي الإنظباطية في الحضور لأنها تكلفك فلوس من راتبك . أيضاً أن الوقت مهم … لازم تقدم شي لأنك تخسّر الشركة لو ما قدمت الشي ( كموظف ) .\n\nاكتشفت أن سوق العمل مو عارف وش طلاب هندسة الحاسب بالظبط !! كثير أعرفهم أشتغلوا شغل الـ ICS و الـ SWE . طبعاً ما أعرف إلا صديق واحد أشتغل في مجال النيتووركنق في التدريب الحالي لكنه كوأب .\n\nأهم نصيحة ممكن أقدمها إنك تظبط نفسك بدري لأن التدريب الصيفي لو أظطريت تأجله بتروح عليك سنة كاملة .\n\nأمنياتي للمهندسين الـ Geeks بالتوفيق 🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-399-summer-training/120823/2", "user": "Sultan11", "ts": 1385172970000, "tid": 120823, "pn": 2}}', 1385172970000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p383390-coe399', 'stk-ghosty', 'COE 399', 'info', '{"desc": "في الحقيقة والواقع أخوي هذا يعتبر تدريب صيفي 🙂\nأنا أخذت التدريب الصيفي مع أرامكو السنة اللي فاتت 072 وكان نفس هذا البرنامج…\n\nبالنسبة لاستفسارك أخوي alfares333, روح للمسؤول عن التدريب الصيفي في قسمك واسأله ان كان القسم يسمحلك تاخذ التدريب مع أرامكو…\n\nالتدريب الصيفي تبع أرامكو للسعوديين فقط واذا تبي توصل للنك حقت التسجيل بعد دخولك لصفحة الموقع الرئيسي:\nJobs & Careers --> Saudis --> Summer Student Programs --> College Students\nطبعا التسجيل ماراح يبدأ الا 21 مارس…\n\nفي النهاية بالنسة لي كCOE ما استفدت من البرنامج لانو ماكان في شغل أغلب وقتي طال عمرك ألعب كانسة الألغام << على فكرة صرت حريف وختمت مستوى Expert ف180 ثانية 👍\n\nبعد ما رجيت السوبرفايسور تبعي كل ساعتين وانا مشقر عليه في المكتب ابي شغل 🥊 تخلص مني ورسلني لPump Station 😦\n\nكل اللي اقدر اقولك عليه في النهاية انو الشغل يعتمد على تخصصك وعلى السوبرفايسور تبعك واهم شي على درجة حماسك للشغل…\n\nبالتوفيق أخوي", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/71729/7", "user": "Ghosty", "ts": 1237452421000, "tid": 71729, "pn": 7}}', 1237452421000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1377291-coe399', 'stk-nigma', 'COE 399', 'info', '{"desc": "إعلان عن توفر فرص تدريب\n\nتعلن شركة ) Fablab Dharan) عن توفر فرص تدريبية التالية في برنامج التدريب الصيفي وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n\n· هندسة ميكانيكة\n· هندسة الحاسب الآلي\n· العمارة\n\nعلى الراغبين في التقدم على هذه الفرص، ارسال السيرة الذاتية على البريد الالكتروني :\n\nb.alsaif@fabladhahran.org\n\nالأستاذ / بدر أكرم السيف\n\nجوال / 0503815230\n\nإدارة التدريب\n\nالتدريييييييب في الجامعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/161274/21", "user": "Nigma", "ts": 1401923484000, "tid": 161274, "pn": 21}}', 1401923484000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p30435-coe399', 'stk-user222', 'COE 399', 'info', '{"desc": "السلام عليكم\nياشباب احد يعرف كم مدة ال presentation لطلاب التدريب الصيفي (هندسة حاسب الي)\nومتى تكون ان شاء الله (في اي اسبوع … الثالث او الخامس … او …)\n\nوسلامتكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/presentation/25281/1", "user": "user222", "ts": 1061498137000, "tid": 25281, "pn": 1}}', 1061498137000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p30482-coe399', 'stk-user447', 'COE 399', 'info', '{"desc": "ارسل الى summer training coordinator الى عندكم في COE واسأله عن اي شي وشيك موقع http://webcourses.kfupm.edu.sa\n\nبالنسبة لي كانت 15 دقيقة او اقل شوي وبحكم اني ماسويت شي يذكر شرحت لهم عن الشركة ووش فيها وبس 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/presentation/25281/2", "user": "user447", "ts": 1061557339000, "tid": 25281, "pn": 2}}', 1061557339000, 1794826849, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
